<div class="modal-backdrop" x-show="modal" x-cloak @click.self="closeModal()"><section class="modal-panel" x-ref="modalPanel" @keydown.tab="trap($event)" role="dialog" aria-modal="true" aria-labelledby="modal-title">
<header class="modal-heading"><div><span class="modal-kicker" x-text="modal==='task'?'یک قدم در مسیر هدف':'فضای کار راستا'"></span><h2 id="modal-title" x-text="({task:taskForm.id?'ویرایش تسک':'تسک جدید',project:'یک پروژه تازه',stage:stageId?'ویرایش مرحله':'مرحله جدید',label:labelForm.id?'ویرایش برچسب':'برچسب جدید',goal:'هدف پروژه',member:'افزودن هم‌تیمی'})[modal]"></h2></div><button class="icon-btn" @click="closeModal()" aria-label="بستن فرم" x-html="$icon('X')"></button></header>
<template x-if="modal==='task'"><form @submit.prevent="saveTask()"><div class="modal-body task-modal-body"><div class="task-project-context"><span x-html="$icon('FolderClosed')"></span><select x-model.number="taskForm.project_id" :disabled="!!taskForm.id" @change="taskForm.stage_id=formProject.stages[0]?.id||'';taskForm.members=[];taskForm.labels=[];taskForm.assigned_to=null" aria-label="پروژه تسک"><template x-for="p in projects" :key="p.id"><option :value="p.id" x-text="p.name"></option></template></select><span class="status-badge" x-show="!canWrite(formProject)">فقط مشاهده</span></div><fieldset :disabled="busy||!canWrite(formProject)">
<label class="task-title-input"><input x-model="taskForm.title" placeholder="عنوان تسک را وارد کنید..." required maxlength="200" aria-label="عنوان تسک"><small class="field-error" x-text="err('title')"></small></label>
<label class="task-description"><textarea x-model="taskForm.description" placeholder="توضیحات تسک را بنویسید..." rows="3" maxlength="10000" aria-label="توضیحات تسک"></textarea><small class="field-error" x-text="err('description')"></small></label>
<div class="subtasks-field"><div class="field-heading"><span x-html="$icon('CheckCheck')"></span><strong>زیرتسک‌ها</strong><span class="muted" x-text="fa(taskForm.subtasks.length)"></span></div><template x-for="(s,i) in taskForm.subtasks" :key="i"><div class="subtask-input" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop.prevent="reorderSubtask(i)"><span class="drag-handle" x-html="$icon('GripVertical')"></span><input type="checkbox" x-model="s.completed" aria-label="تکمیل زیرتسک"><input x-model="s.title" placeholder="عنوان زیرتسک" required maxlength="200"><button type="button" class="icon-btn" @click="taskForm.subtasks.splice(i,1)" aria-label="حذف زیرتسک" x-html="$icon('X')"></button><button type="button" class="icon-btn" @click="if(i>0){dragIndex=i;reorderSubtask(i-1)}" aria-label="جابجایی زیرتسک به بالا" x-html="$icon('ChevronRight')"></button></div></template><button class="text-button accent" type="button" @click="addSubtask()"><span x-html="$icon('Plus')"></span>افزودن زیرتسک</button><small class="field-error" x-text="Object.keys(errors).filter(k=>k.startsWith('subtasks')).map(k=>err(k)).join(' ')"></small></div>
<div class="task-fields">
<label><span class="field-heading"><span x-html="$icon('LayoutGrid')"></span>مرحله محصول</span><select x-model.number="taskForm.stage_id" required><option value="" disabled>انتخاب مرحله</option><template x-for="s in formProject?.stages||[]" :key="s.id"><option :value="s.id" x-text="s.title"></option></template><option value="new">＋ ساخت مرحله جدید</option></select><small class="field-error" x-text="err('stage_id')"></small></label>
<div x-effect="if(taskForm.stage_id==='new'&&!inlineStage)startInlineStage()"></div><button class="text-button accent inline-new-stage" type="button" @click="startInlineStage()" x-show="!inlineStage"><span x-html="$icon('Plus')"></span>ساخت مرحله جدید</button>
<div class="inline-form" x-show="inlineStage"><h3>مرحله جدید</h3><label>عنوان<input x-model="inlineStageForm.title" placeholder="مثلاً طراحی رابط کاربری"><small class="field-error" x-text="err('title')"></small></label><label>توضیحات<input x-model="inlineStageForm.description" placeholder="توضیح کوتاه (اختیاری)"></label><div class="form-grid"><label>شروع<x-date-picker model="inlineStageForm.start_date" /></label><label>پایان<x-date-picker model="inlineStageForm.end_date" /></label></div><div class="button-row"><button type="button" class="button primary small-button" @click="createInlineStage()">ساخت و انتخاب مرحله</button><button type="button" class="text-button" @click="inlineStage=false;taskForm.stage_id=formProject.stages[0]?.id||''">انصراف</button></div></div>
<label><span class="field-heading"><span x-html="$icon('Users')"></span>مسئول تسک</span><select x-model.number="taskForm.assigned_to"><option :value="null">بدون مسئول</option><template x-for="m in formProject?.members||[]" :key="m.id"><option :value="m.id" x-text="m.name"></option></template></select><small class="field-error" x-text="err('assigned_to')"></small></label>
<div class="related-members"><span class="small-label">اعضای مرتبط</span><div class="member-options"><template x-for="m in formProject?.members||[]" :key="m.id"><label class="member-choice"><input type="checkbox" :value="m.id" x-model.number="taskForm.members"><span class="avatar tiny" :style="`background:${color(m.id)}`" x-text="initials(m.name)"></span><span x-text="m.name"></span></label></template></div></div>
<label x-show="formProject?.member_stages.length"><span class="small-label">مرحله تیمی (اختیاری)</span><select x-model.number="taskForm.member_stage_id"><option :value="null">بدون مرحله تیمی</option><template x-for="s in formProject?.member_stages||[]" :key="s.id"><option :value="s.id" x-text="member(s.user_id).name+' / '+s.title"></option></template></select></label>
<div class="labels-field"><div class="field-heading"><span x-html="$icon('Tags')"></span><strong>برچسب‌ها</strong></div><input class="label-search" x-model="labelQuery" placeholder="جست‌وجو یا ساخت برچسب..."><div class="label-options"><template x-for="l in formLabels" :key="l.id"><label class="tag selectable" :style="`--tag-color:${l.color}`" :class="{'chosen':taskForm.labels.includes(l.id)}"><input type="checkbox" :value="l.id" x-model.number="taskForm.labels"><i></i><span x-text="l.name"></span></label></template><button type="button" class="text-button accent" x-show="labelQuery&&!formLabels.some(l=>l.name===labelQuery)" @click="quickLabel()"><span x-html="$icon('Plus')"></span><span x-text="'ساخت «'+labelQuery+'»'"></span></button></div><small class="field-error" x-text="err('labels')"></small></div>
<div class="form-grid"><label><span class="field-heading"><span x-html="$icon('CalendarDays')"></span>تاریخ شروع</span><x-date-picker model="taskForm.start_date" label="تاریخ شروع تسک" /><small class="field-error" x-text="err('start_date')"></small></label><label><span class="field-heading"><span x-html="$icon('Flag')"></span>مهلت انجام</span><x-date-picker model="taskForm.due_date" label="مهلت تسک" /><small class="field-error" x-text="err('due_date')"></small></label></div>
<div class="attachments-field"><div class="field-heading"><span x-html="$icon('Paperclip')"></span><strong>پیوست‌ها</strong></div><label class="upload-zone" @dragover.prevent @drop.prevent="filesAdded($event.dataTransfer.files)"><input type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.txt" @change="filesAdded($event.target.files);$event.target.value=''" class="sr-only"><span x-html="$icon('Upload')"></span><strong>فایل را اینجا رها کنید یا انتخاب کنید</strong><small>تصویر، PDF یا متن · حداکثر ۵ مگابایت</small></label><small class="field-error" x-text="err('file')"></small><template x-for="(f,i) in pendingFiles" :key="i"><div class="attachment-row"><span x-html="$icon('Paperclip')"></span><span x-text="f.name"></span><small x-text="size(f.size)"></small><button type="button" class="icon-btn" @click="pendingFiles.splice(i,1)" aria-label="برداشتن فایل" x-html="$icon('X')"></button></div></template></div>
</div></fieldset>
<template x-for="a in taskForm.attachments" :key="a.id"><div class="attachment-row"><span x-html="$icon('Paperclip')"></span><div><a :href="'/attachments/'+a.id" x-text="a.original_name"></a><small x-text="size(a.size)+' · '+a.mime_type+' · '+a.user?.name+' · '+new Date(a.created_at).toLocaleDateString('fa-IR')"></small></div><button type="button" class="icon-btn" x-show="canWrite(formProject)&&(a.user_id===user.id||isOwner(formProject))" @click="deleteAttachment(a)" aria-label="حذف پیوست" x-html="$icon('Trash2')"></button></div></template>
<div class="comments-field"><div class="field-heading"><span x-html="$icon('MessageCircle')"></span><strong>گفت‌وگو درباره این تسک</strong></div><template x-for="c in taskForm.comments" :key="c.id"><div class="comment"><span class="avatar small" :style="`background:${color(c.user_id)}`" x-text="initials(c.user?.name)"></span><div class="comment-content"><div><strong x-text="c.user?.name"></strong><small x-text="new Date(c.created_at).toLocaleString('fa-IR')"></small></div><p x-show="!c.editing" x-text="c.body"></p><div x-show="c.editing"><textarea x-model="c.editBody" rows="2"></textarea><button class="text-button accent" type="button" @click="editComment(c)">ذخیره</button><button class="text-button" type="button" @click="c.editing=false">انصراف</button></div><div class="comment-actions" x-show="c.user_id===user.id&&canWrite(formProject)"><button type="button" @click="c.editing=true;c.editBody=c.body">ویرایش</button><button type="button" @click="deleteComment(c)">حذف</button></div></div></div></template><div class="new-comment" x-show="canWrite(formProject)"><span class="avatar small" :style="`background:${color(user.id)}`" x-text="initials(user.name)"></span><textarea x-model="commentText" placeholder="نظرتان را بنویسید..." rows="2" maxlength="5000"></textarea><button type="button" class="icon-btn accent" x-show="taskForm.id" @click="addComment()" :disabled="busy||!commentText.trim()" aria-label="ارسال نظر" x-html="$icon('ArrowUpLeft')"></button></div><small class="field-error" x-text="err('body')"></small></div>
</div><footer class="modal-footer"><div><button type="button" class="icon-btn danger-text" x-show="taskForm.id&&canWrite(formProject)" @click="removeTask()" aria-label="حذف تسک" x-html="$icon('Trash2')"></button><label class="complete-label" x-show="taskForm.id"><input type="checkbox" x-model="taskForm.completed" :disabled="!canWrite(formProject)">تکمیل شده</label></div><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy" x-show="canWrite(formProject)" x-text="busy?'در حال ذخیره...':taskForm.id?'ذخیره تغییرات':'ساخت تسک'"></button></div></footer></form></template>
<template x-if="modal==='project'"><form @submit.prevent="projectStep<3?nextStep():saveProject()"><div class="wizard-steps"><template x-for="(title,i) in ['اطلاعات پروژه','هدف پروژه','مراحل مسیر']" :key="i"><div :class="{'current':projectStep===i+1,'done':projectStep>i+1}"><span x-text="projectStep>i+1?'✓':fa(i+1)"></span><strong x-text="title"></strong></div></template></div><div class="modal-body"><div x-show="projectStep===1"><div class="form-intro"><h3>چه چیزی می‌خواهید بسازید؟</h3><p>با یک نام و توضیح کوتاه، به پروژه‌تان هویت بدهید.</p></div><label>نام پروژه<input x-model="projectForm.name" placeholder="مثلاً سامانه رزرو هتل" maxlength="150"><small class="field-error" x-text="err('name')"></small></label><label>توضیح کوتاه<textarea x-model="projectForm.description" placeholder="این پروژه درباره چیست؟" rows="3"></textarea></label></div><div x-show="projectStep===2"><div class="helper-box"><span x-html="$icon('Target')"></span><p>ابتدا هدف پروژه را مشخص کنید. مراحل پروژه، مسیر رسیدن به این هدف خواهند بود.</p></div><label>عنوان هدف<input x-model="projectForm.goal.title" placeholder="مثلاً راه‌اندازی نسخه اول سامانه رزرو هتل"><small class="field-error" x-text="err('goal.title')"></small></label><label>توضیح هدف<textarea x-model="projectForm.goal.description" rows="2" placeholder="می‌خواهیم به چه نتیجه‌ای برسیم؟"></textarea></label><label>معیار موفقیت<textarea x-model="projectForm.goal.success_criteria" rows="2" placeholder="از کجا بفهمیم به هدف رسیده‌ایم؟"></textarea><small class="field-error" x-text="err('goal.success_criteria')"></small></label><div class="form-grid"><label>تاریخ شروع<x-date-picker model="projectForm.goal.start_date" /><small class="field-error" x-text="err('goal.start_date')"></small></label><label>تاریخ هدف<x-date-picker model="projectForm.goal.end_date" /><small class="field-error" x-text="err('goal.end_date')"></small></label></div></div><div x-show="projectStep===3"><div class="form-intro"><h3>مسیر رسیدن به هدف را بسازید</h3><p>مرحله‌ها را بکشید و به ترتیب دلخواه بچینید.</p></div><template x-for="(s,i) in projectForm.stages" :key="i"><div class="wizard-stage" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop.prevent="dropWizard(i)"><div class="wizard-stage-title"><span x-html="$icon('GripVertical')"></span><span class="step-number" x-text="fa(i+1)"></span><input x-model="s.title" placeholder="نام مرحله"><button type="button" class="icon-btn" @click="moveWizard(i,-1)" aria-label="مرحله قبل" x-html="$icon('ChevronRight')"></button><button type="button" class="icon-btn" @click="projectForm.stages.splice(i,1)" aria-label="حذف مرحله" x-html="$icon('Trash2')"></button></div><input x-model="s.description" placeholder="توضیح کوتاه (اختیاری)"><div class="form-grid"><label>شروع<x-date-picker model="s.start_date" /></label><label>پایان<x-date-picker model="s.end_date" /></label></div><small class="field-error" x-text="Object.keys(errors).filter(k=>k.startsWith('stages.'+i+'.')).map(k=>err(k)).join(' ')"></small></div></template><button type="button" class="button full-width dashed" @click="projectForm.stages.push({title:'',description:'',start_date:projectForm.goal.start_date,end_date:projectForm.goal.end_date})"><span x-html="$icon('Plus')"></span>افزودن مرحله</button><small class="field-error" x-text="err('stages')"></small></div></div><footer class="modal-footer"><span class="muted" x-text="'مرحله '+fa(projectStep)+' از ۳'"></span><div class="button-row"><button type="button" class="button" @click="projectStep>1?projectStep--:closeModal()" x-text="projectStep>1?'قبلی':'انصراف'"></button><button class="button primary" type="submit" :disabled="busy" x-text="busy?'در حال ساخت...':projectStep===3?'ساخت پروژه':'ادامه'"></button></div></footer></form></template>
<template x-if="modal==='stage'"><form @submit.prevent="saveStage()"><div class="modal-body"><div class="helper-box" x-show="stageUser"><span x-html="$icon('Users')"></span><p x-text="'مسیر اختصاصی '+stageUser?.name"></p></div><label>نام مرحله<input x-model="stageForm.title" required maxlength="120"><small class="field-error" x-text="err('title')"></small></label><label>توضیحات<textarea x-model="stageForm.description" rows="3"></textarea></label><div class="form-grid"><label>شروع<x-date-picker model="stageForm.start_date" /><small class="field-error" x-text="err('start_date')"></small></label><label>پایان<x-date-picker model="stageForm.end_date" /><small class="field-error" x-text="err('end_date')"></small></label></div></div><footer class="modal-footer"><button type="button" class="text-button danger-text" x-show="stageId&&canWrite(currentProject)" @click="deleteStage({id:stageId},stageKind)">حذف مرحله</button><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy||!canWrite(currentProject)">ذخیره مرحله</button></div></footer></form></template>
<template x-if="modal==='goal'"><form @submit.prevent="saveGoal()"><div class="modal-body"><label>عنوان هدف<input x-model="goalForm.title" required><small class="field-error" x-text="err('title')"></small></label><label>توضیح هدف<textarea x-model="goalForm.description" rows="3"></textarea></label><label>معیار موفقیت<textarea x-model="goalForm.success_criteria" required rows="3"></textarea><small class="field-error" x-text="err('success_criteria')"></small></label><div class="form-grid"><label>شروع<x-date-picker model="goalForm.start_date" /></label><label>پایان<x-date-picker model="goalForm.end_date" /><small class="field-error" x-text="err('end_date')"></small></label></div></div><footer class="modal-footer"><span></span><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy">ذخیره هدف</button></div></footer></form></template>
<template x-if="modal==='label'"><form @submit.prevent="saveLabel()"><div class="modal-body"><label>نام برچسب<input x-model="labelForm.name" required maxlength="60"><small class="field-error" x-text="err('name')"></small></label><label>رنگ<div class="color-picker"><input type="color" x-model="labelForm.color"><template x-for="c in ['#ed8555','#9274be','#568c7b','#527fa9','#bb6073','#9b864f']"><button type="button" :style="`background:${c}`" @click="labelForm.color=c" :aria-label="'انتخاب رنگ '+c" :class="{'chosen':labelForm.color===c}"></button></template></div></label><label>توضیحات (اختیاری)<textarea x-model="labelForm.description" rows="2"></textarea></label><label x-show="!labelForm.id">محدوده برچسب<select x-model.number="labelForm.project_id"><option :value="null">شخصی، در همه پروژه‌ها</option><template x-for="p in projects.filter(p=>canWrite(p))" :key="p.id"><option :value="p.id" x-text="p.name"></option></template></select></label></div><footer class="modal-footer"><span class="tag" :style="`--tag-color:${labelForm.color}`" x-text="labelForm.name||'پیش‌نمایش'"></span><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy">ذخیره برچسب</button></div></footer></form></template>
<template x-if="modal==='member'"><form @submit.prevent="saveMember()"><div class="modal-body"><div class="helper-box"><span x-html="$icon('Users')"></span><p>ایمیل هم‌تیمی‌ای را وارد کنید که در راستا حساب دارد.</p></div><label>ایمیل هم‌تیمی<input type="email" dir="ltr" x-model="memberForm.email" required placeholder="name@example.com"><small class="field-error" x-text="err('email')"></small></label><label>نقش<select x-model="memberForm.role"><option value="member">عضو — همکاری روی تسک‌ها و مراحل</option><option value="viewer">بیننده — فقط مشاهده</option></select></label></div><footer class="modal-footer"><span></span><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy">افزودن عضو</button></div></footer></form></template>
</section></div>
